int longestConsecutive(const std::vector<int>& a) {
    std::unordered_set<int> s(a.begin(), a.end());
    int best = 0;
    for (int x : s) {
        if (x != INT_MIN && s.count(x - 1)) continue;
        int len = 1;
        for (int cur = x; cur != INT_MAX && s.count(cur + 1); cur++)
            len++;
        best = std::max(best, len);
    }
    return best;
}

