from collections import defaultdict

def group_anagrams(words):
    g = defaultdict(list)
    for w in words:
        g[sorted(w)].append(w)
    return list(g.values())

def near_dup(nums, k):
    last = {}
    for i, x in enumerate(nums):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False

